59	        assertEquals(ErrorCode.ROOM_UNAVAILABLE,
60	                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.STANDARD))));
61	        // the check-out day is free for the next guest, and another room is free on the same nights
62	        service.create(stay(201, "2027-03-13", "2027-03-15", 2, RatePlan.STANDARD));
